#include <bits/stdc++.h>
using namespace std;

int L, C;
vector<string> g;

bool inside(int r, int c) {
    return r >= 0 && r < L && c >= 0 && c < C;
}

int main() {
    if (scanf("%d %d", &L, &C) != 2) return 0;
    g.assign(L, "");
    char buf[256];
    for (int i = 0; i < L; i++) {
        scanf("%s", buf);
        g[i] = buf;
    }

    int sr = -1, sc = -1;
    for (int i = 0; i < L; i++)
        for (int j = 0; j < C; j++)
            if (g[i][j] == 'o') { sr = i; sc = j; }

    const int dr[4] = {-1, 1, 0, 0};
    const int dc[4] = {0, 0, -1, 1};

    // Vai para o unico vizinho 'H' da posicao inicial 'o'
    int pr = sr, pc = sc; // posicao anterior (onde veio)
    int cr = -1, cc = -1; // posicao atual
    for (int d = 0; d < 4; d++) {
        int r = sr + dr[d], c = sc + dc[d];
        if (inside(r, c) && g[r][c] == 'H') { cr = r; cc = c; }
    }

    // Caminha: Move sempre para o vizinho 'H' que nao seja o de onde veio.
    // Para quando o unico vizinho 'H' da celula atual e exatamente o anterior.
    while (true) {
        int nr = -1, nc = -1;
        for (int d = 0; d < 4; d++) {
            int r = cr + dr[d], c = cc + dc[d];
            if (inside(r, c) && g[r][c] == 'H' && !(r == pr && c == pc)) {
                nr = r; nc = c;
                break;
            }
        }
        if (nr == -1) break; // chegou: sem vizinho 'H' diferente do anterior
        pr = cr; pc = cc;
        cr = nr; cc = nc;
    }

    printf("%d %d\n", cr + 1, cc + 1);
    return 0;
}
